b:if.script:
//
document.querySelectorAll('.post-card').forEach(function(card) {
  var hiddenDiv = card.querySelector('.hidden-labels');
  if (!hiddenDiv) return;
  var labelsText = hiddenDiv.textContent || hiddenDiv.innerText;
  var labels = labelsText.split(',');
  var version = null;
  var format = null;
  var rating = null;
  var firstLabel = labels.length > 0 ? labels[0].trim() : null;

  // Buscar etiqueta de formato (w) – guardamos sin la w
  for (var i = 0; i < labels.length; i++) {
    var lbl = labels[i].trim();
    if (lbl.toLowerCase().match(/^w/)) {
      format = lbl.substring(1); // elimina la primera letra (w)
      break;
    }
  }

  // Si no hay formato, buscar versión (v)
  if (!format) {
    for (var i = 0; i < labels.length; i++) {
      var lbl = labels[i].trim();
      if (lbl.toLowerCase().match(/^v\d+(\.\d+)*/)) {
        version = lbl;
        break;
      }
    }
  }

  // Buscar rating (z)
  for (var i = 0; i < labels.length; i++) {
    var lbl = labels[i].trim();
    var match = lbl.toLowerCase().match(/^z(\d+(?:\.\d+)?)/);
    if (match) {
      rating = parseFloat(match[1]);
      break;
    }
  }

  // Actualizar el bloque de versión/formato
  var versionDiv = card.querySelector('.post-card__version');
  var versionSpan = card.querySelector('.version-value');
  if (versionDiv && versionSpan) {
    if (format) {
      versionDiv.childNodes[0].textContent = 'Formato: ';
      versionSpan.textContent = format;   // aquí ya no lleva la w
      versionDiv.style.display = 'inline-block';
    } else if (version) {
      versionDiv.childNodes[0].textContent = 'Versión: ';
      versionSpan.textContent = version;
      versionDiv.style.display = 'inline-block';
    } else {
      versionDiv.style.display = 'none';
    }
  }

  // Estrellas
  var starsDiv = card.querySelector('.rating-stars');
  if (starsDiv && rating !== null && !isNaN(rating)) {
    var fullStars = Math.floor(rating);
    var partialFill = rating - fullStars;
    var starHtml = '';
    for (var s = 0; s < 5; s++) {
      if (s < fullStars) {
        starHtml += '<div class="rating-star full"></div>';
      } else if (s === fullStars && partialFill > 0) {
        var percent = Math.round(partialFill * 100);
        starHtml += '<div class="rating-star" style="background: linear-gradient(to right, #ffd700 ' + percent + '%, #e0e0e0 ' + percent + '%);"></div>';
      } else {
        starHtml += '<div class="rating-star empty"></div>';
      }
    }
    starsDiv.innerHTML = starHtml;
    starsDiv.style.display = 'flex';
  } else if (starsDiv) {
    starsDiv.style.display = 'none';
  }

  // Etiqueta superpuesta
  var tagDiv = card.querySelector('.post-card__featured-tag');
  if (tagDiv && firstLabel) {
    tagDiv.textContent = firstLabel;
    tagDiv.style.display = 'block';
  } else if (tagDiv) {
    tagDiv.style.display = 'none';
  }
});
